252	function layered(items,edges,opt){
253	const LR=opt.LR;
254	const ids=items.map((n)=>n.id);
255	const item=new Map(items.map((n)=>[n.id,n]));
256	const out=new Map(ids.map((id)=>[id,[]]));
257	const inn=new Map(ids.map((id)=>[id,[]]));
258	edges.forEach((e,i)=>{e.i=i;out.get(e.from).push(e);inn.get(e.to).push(e);});
259	const seen=new Map();
260	const cut=new Set();
261	const dfs=(u)=>{
262	seen.set(u,1);
263	for(const e of out.get(u)){
264	const st=seen.get(e.to);
265	if(st===1)cut.add(e.i);
266	else if(!st)dfs(e.to);
267	}
268	seen.set(u,2);
269	};
270	ids.filter((id)=>!inn.get(id).length).forEach((id)=>{if(!seen.get(id))dfs(id);});
271	ids.forEach((id)=>{if(!seen.get(id))dfs(id);});
272	const zones=opt.zones||[];
273	const zoneIndex=new Map(zones.map((z,i)=>[z.id,i]));
274	const stage=opt.zoneMode==='stage'&&zones.length&&items.every((n)=>zoneIndex.has(n.zone));
275	const rank=new Map();
276	const longest=(sameZoneOnly)=>{
277	const indeg=new Map(ids.map((id)=>[id,0]));
278	const usable=edges.filter((e)=>!cut.has(e.i)&&(!sameZoneOnly||item.get(e.from).zone===item.get(e.to).zone));
279	usable.forEach((e)=>indeg.set(e.to,indeg.get(e.to)+1));
280	const queue=ids.filter((id)=>!indeg.get(id));
281	const local=new Map(ids.map((id)=>[id,0]));
282	while(queue.length){
283	const u=queue.shift();
284	for(const e of usable.filter((x)=>x.from===u)){
285	local.set(e.to,Math.max(local.get(e.to),local.get(u)+1));
286	indeg.set(e.to,indeg.get(e.to)-1);
287	if(!indeg.get(e.to))queue.push(e.to);
288	}
289	}
290	return local;
291	};
292	if(stage){
293	const local=longest(true);
294	let base=0;
295	for(const z of zones){
296	const members=ids.filter((id)=>item.get(id).zone===z.id);
297	members.forEach((id)=>rank.set(id,base+local.get(id)));
298	base+=members.length?Math.max(...members.map((id)=>local.get(id)))+1:0;
299	}
300	}else{
301	longest(false).forEach((v,id)=>rank.set(id,v));
302	}
303	const back=new Set(edges.filter((e)=>rank.get(e.to)<=rank.get(e.from)).map((e)=>e.i));
304	const forward=edges.filter((e)=>!back.has(e.i));
305	const best=new Map();
306	const prev=new Map();
307	const tied=new Map();
308	const byRank=[...ids].sort((a,b)=>rank.get(a)-rank.get(b));
309	for(const u of byRank){
310	if(item.get(u).offPath)continue;
311	if(!best.has(u))best.set(u,1);
312	for(const e of forward.filter((x)=>x.from===u)){
313	if(item.get(e.to).offPath)continue;
314	if((best.get(e.to)||0)<best.get(u)+1){best.set(e.to,best.get(u)+1);tied.set(e.to,[u]);}
315	else if(best.get(e.to)===best.get(u)+1)tied.get(e.to).push(u);
316	}
317	}
318	tied.forEach((list,id)=>prev.set(id,list[(list.length-1)>>1]));
319	let tail=null;
320	for(const u of byRank){
321	if(!best.has(u))continue;
322	if(!tail||best.get(u)>best.get(tail)||(best.get(u)===best.get(tail)&&item.get(u).goal))tail=u;
323	}
324	const spine=new Set();
325	for(let u=tail;u;u=prev.get(u))spine.add(u);
326	const maxRank=Math.max(0,...rank.values());
327	const ranks=Array.from({length:maxRank+1},()=>[]);
328	ids.forEach((id)=>ranks[rank.get(id)].push(id));
329	const crossSize=new Map(items.map((n)=>[n.id,LR?n.h:n.w]));
330	const rankSize=new Map(items.map((n)=>[n.id,LR?n.w:n.h]));
331	const lane=new Map(items.map((n)=>[n.id,zoneIndex.has(n.zone)?zoneIndex.get(n.zone):zones.length]));
332	const nb=new Map([...ids].map((id)=>[id,{p:[],s:[]}]));
333	const dummies=[];
334	const chain=new Map();
335	for(const e of forward){
336	let last=e.from;
337	for(let r=rank.get(e.from)+1;r<rank.get(e.to);r++){
338	const d=`~${e.i}~${r}`;
339	dummies.push(d);
340	if(!chain.has(e.i))chain.set(e.i,[]);
341	chain.get(e.i).push(d);
342	rank.set(d,r);
343	ranks[r].push(d);
344	crossSize.set(d,16);
345	lane.set(d,lane.get(e.from));
346	nb.set(d,{p:[],s:[]});
347	nb.get(last).s.push(d);
348	nb.get(d).p.push(last);
349	last=d;
350	}
351	nb.get(last).s.push(e.to);
352	nb.get(e.to).p.push(last);
353	}
354	const order=new Map();
355	const reindex=()=>ranks.forEach((list)=>list.forEach((id,i)=>order.set(id,i)));
356	reindex();
357	const laneMode=opt.zoneMode==='lane';
358	const stacked=laneMode||!!opt.stack;
359	const zoned=opt.zoneMode==='group'&&!stacked;
360	const sortRank=(list,side)=>{
361	const key=new Map(list.map((id)=>{
362	const ns=nb.get(id)[side];
363	return[id,ns.length?ns.reduce((a,v)=>a+order.get(v),0)/ns.length:order.get(id)];
364	}));
365	list.sort((a,b)=>{
366	if(stacked&&lane.get(a)!==lane.get(b))return lane.get(a)-lane.get(b);
367	if(key.get(a)!==key.get(b))return key.get(a)-key.get(b);
368	if(spine.has(a)!==spine.has(b))return spine.has(a)?-1:1;
369	const oa=item.has(a)&&item.get(a).offPath,ob=item.has(b)&&item.get(b).offPath;
370	if(oa!==ob)return oa?1:-1;
371	return 0;
372	});
373	const off=(id)=>item.has(id)&&item.get(id).offPath;
374	for(let i=0,j;i<list.length;i=j){
375	for(j=i+1;j<list.length&&key.get(list[j])===key.get(list[i])&&lane.get(list[j])===lane.get(list[i])&&off(list[j])===off(list[i]);j++);
376	if(j-i>2&&spine.has(list[i])&&!off(list[i]))list.splice(i+((j-i-1)>>1),0,list.splice(i,1)[0]);
377	}
378	};
379	for(let pass=0;pass<2;pass++){
380	for(let r=1;r<=maxRank;r++){sortRank(ranks[r],'p');reindex();}
381	for(let r=maxRank-1;r>=0;r--){sortRank(ranks[r],'s');reindex();}
382	}
383	const cross=new Map();
384	const pav=(rows)=>{
385	const blocks=[];
386	for(const it of rows){
387	blocks.push({sum:it.w*(it.d-it.off),w:it.w,n:1});
388	while(blocks.length>1){
389	const b2=blocks[blocks.length-1],b1=blocks[blocks.length-2];
390	if(b1.sum/b1.w<=b2.sum/b2.w)break;
391	blocks.splice(blocks.length-2,2,{sum:b1.sum+b2.sum,w:b1.w+b2.w,n:b1.n+b2.n});
392	}
393	}
394	const q=[];
395	for(const b of blocks)for(let k=0;k<b.n;k++)q.push(b.sum/b.w);
396	return rows.map((it,i)=>q[i]+it.off);
397	};
398	const half=(id)=>(opt.top&&LR?0:crossSize.get(id)/2);
399	const mid=(id)=>snap(cross.get(id))-half(id)+crossSize.get(id)/2;
400	const gapBetween=(a,b)=>(zoned&&lane.get(a)!==lane.get(b)?CROSS_GAP+ZONE_HEAD+ZONE_PAD+ZONE_GAP:CROSS_GAP);
401	const place=(whole,desired)=>{
402	const parts=stacked?[...new Set(whole.map((id)=>lane.get(id)))].map((k)=>whole.filter((id)=>lane.get(id)===k)):[whole];
403	for(const list of parts){
404	let off=0;
405	const rows=list.map((id,i)=>{
406	if(i>0)off+=crossSize.get(list[i-1])-half(list[i-1])+half(id)+gapBetween(list[i-1],id);
