const h = (hex) => ({ r: parseInt(hex.slice(1, 3), 16) / 255, g: parseInt(hex.slice(3, 5), 16) / 255, b: parseInt(hex.slice(5, 7), 16) / 255 })
const board = await figma.getNodeByIdAsync('1:3')
const before = { w: board.width, h: board.height }
const origin = board.absoluteBoundingBox
const rel = async (id) => {
  const n = await figma.getNodeByIdAsync(id)
  const b = n.absoluteBoundingBox
  return { x: b.x - origin.x, y: b.y - origin.y, w: b.width, h: b.height }
}
const cancelled = await rel('1:37')
const cancelledEnd = await rel('1:44')
const noShow = await rel('1:12')
const noShowEnd = await rel('1:47')
const probe = figma.createSticky()
await figma.loadFontAsync(probe.text.fontName)
probe.remove()
const notes = [
  { name: 'note:1', text: 'Cancelled: set by the guest' },
  { name: 'note:2', text: 'No-show: set by the hotel' },
]
const stickies = notes.map((n) => {
  const s = figma.createSticky()
  s.name = n.name
  s.text.characters = n.text
  s.fills = [{ type: 'SOLID', color: h('#A8DAFF') }]
  board.appendChild(s)
  return s
})
const [sCancelled, sNoShow] = stickies
const col = Math.ceil((Math.max(cancelledEnd.x + cancelledEnd.w, noShowEnd.x + noShowEnd.w) + 64) / 8) * 8
const yNoShow = Math.round((noShowEnd.y + noShowEnd.h / 2 - sNoShow.height / 2) / 8) * 8
const yCancelled = Math.max(Math.round((cancelledEnd.y + cancelledEnd.h / 2 - sCancelled.height / 2) / 8) * 8, yNoShow + sNoShow.height + 64)
sNoShow.x = col
sNoShow.y = yNoShow
sCancelled.x = col
sCancelled.y = yCancelled
const right = col + sNoShow.width
const bottom = Math.max(yCancelled + sCancelled.height, board.height - 80)
board.resizeWithoutConstraints(Math.max(board.width, Math.ceil((right + 80) / 8) * 8), Math.max(board.height, Math.ceil((bottom + 80) / 8) * 8))
await board.screenshot({ scale: Math.min(1, 1600 / board.width) })
return {
  createdNodeIds: stickies.map((s) => s.id),
  boardBefore: before,
  boardAfter: { w: board.width, h: board.height },
  placed: stickies.map((s) => ({ name: s.name, id: s.id, x: s.x, y: s.y, w: s.width, h: s.height, text: s.text.characters })),
  targets: { cancelled, cancelledEnd, noShow, noShowEnd },
}

